"""build.py: makes the generated files of the learnings database from their sources, then checks them.

Sources: _build/lists.json (the lists and the columns), base/template/learnings.csv (twelve
invented rows) and base/SKILL.md. Writes, each marked as generated:
  base/template/learnings.xlsx                     the template: Learnings, Lists and How to use tabs
  level-2-files/claude-plugin/learnings-database/  the Claude plugin: the skill and three commands
Checks: the CSV header is the column list; every row uses listed values; each rule starts "When "
and is at most 25 words; SKILL.md names every area and lesson type, holds the header, and stays
under 300 lines; schema.sql seeds the same lists.
Run: python3 projects/learnings-database/_build/build.py   (needs: openpyxl)
"""
import csv, json, os, shutil, sys
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill
from openpyxl.worksheet.datavalidation import DataValidation

here = os.path.dirname(os.path.abspath(__file__))
root = os.path.dirname(here)
L = json.load(open(os.path.join(here, "lists.json")))
GEN = "GENERATED by _build/build.py from _build/lists.json and base/template/learnings.csv. Edit those, not this."
problems = []

# 1. check the template rows
path = os.path.join(root, "base", "template", "learnings.csv")
rows = list(csv.DictReader(open(path)))
if open(path).readline().strip().split(",") != L["columns"]:
    problems.append("the CSV header is not the column list")
allowed = {"kind": {k["value"] for k in L["kinds"]}, "area": {a["value"] for a in L["areas"]},
           "lesson_type": {t["value"] for t in L["lesson_types"]}, "project": set(L["projects"]) | {""},
           "severity": {"low", "medium", "high"}, "status": {"proposed", "accepted", "merged", "retired"},
           "source": {"chat", "review", "person", "agent", "import"}, "sensitive": {"yes", "no"},
           "confidence": {"high", "medium", "low", ""}}
for r in rows:
    for col, ok in allowed.items():
        if r[col] not in ok: problems.append(f"{r['id']}: {col} = {r[col]!r} is not on the list")
    if not r["rule"].startswith("When "): problems.append(f"{r['id']}: the rule should start 'When '")
    if len(r["rule"].split()) > 25: problems.append(f"{r['id']}: the rule is over 25 words")

# 2. the spreadsheet template
wb = Workbook(); ws = wb.active; ws.title = "Learnings"
ws.append(L["columns"])
for r in rows: ws.append([int(r[c]) if c == "seen" else r[c] for c in L["columns"]])
head = PatternFill("solid", fgColor="E8E4F7")
for c in ws[1]: c.font = Font(bold=True); c.fill = head
ws.freeze_panes = "A2"
widths = {"rule": 60, "what_happened": 50, "expected": 40, "why": 40, "tags": 30, "area": 16, "lesson_type": 14, "project": 22}
for i, col in enumerate(L["columns"], 1):
    ws.column_dimensions[ws.cell(1, i).column_letter].width = widths.get(col, 12)
ls = wb.create_sheet("Lists"); ls.append(["list", "value", "means"])
for k in L["kinds"]: ls.append(["kind", k["value"], k["means"]])
for a in L["areas"]: ls.append(["area", a["value"], a["means"]])
for t in L["lesson_types"]: ls.append(["lesson_type", t["value"], t["means"]])
for p in L["projects"]: ls.append(["project", p, "An invented example project. Replace with your own"])
for c in ls[1]: c.font = Font(bold=True); c.fill = head
ls.column_dimensions["A"].width = 14; ls.column_dimensions["B"].width = 20; ls.column_dimensions["C"].width = 80
n = ls.max_row
def rng(name):
    idx = [i for i in range(2, n + 1) if ls.cell(i, 1).value == name]
    return f"Lists!$B${idx[0]}:$B${idx[-1]}"
for col, name in [("C", "kind"), ("D", "area"), ("E", "project"), ("F", "lesson_type")]:
    dv = DataValidation(type="list", formula1=rng(name), allow_blank=True, showErrorMessage=False)
    ws.add_data_validation(dv); dv.add(f"{col}2:{col}2000")
for col, vals in [("L", "low,medium,high"), ("M", "proposed,accepted,merged,retired"), ("P", "yes,no"), ("Q", "high,medium,low")]:
    dv = DataValidation(type="list", formula1=f'"{vals}"', allow_blank=True, showErrorMessage=False)
    ws.add_data_validation(dv); dv.add(f"{col}2:{col}2000")
how = wb.create_sheet("How to use")
for line in [
    "Learnings database: your log of what went wrong, what had to be redone and what worked better than usual.",
    "The twelve rows on the Learnings tab are invented examples. Delete them when you add your own.",
    "",
    "One row is one lesson. The rule column is the lesson as one instruction: When ..., do ...",
    "Only you change status: proposed (new), accepted (use it), merged (folded into another row), retired (no longer true).",
    "seen counts how many times it happened. It should stop rising once the rule is followed.",
    "sensitive = yes keeps a row out of anything pasted elsewhere. An empty cell counts as yes.",
    "Put your own projects on the Lists tab. The assistant uses what is there.",
    "",
    "To use it: https://github.com/bar181/practical-ai/tree/main/projects/learnings-database",
    GEN,
]:
    how.append([line])
how.column_dimensions["A"].width = 120; how["A1"].font = Font(bold=True, size=13)
wb.save(os.path.join(root, "base", "template", "learnings.xlsx"))

# 3. check the skill and the database lists
skill = open(os.path.join(root, "base", "SKILL.md")).read()
for a in L["areas"]:
    if f"`{a['value']}`" not in skill: problems.append(f"SKILL.md does not name the area {a['value']}")
for t in L["lesson_types"]:
    if f"`{t['value']}`" not in skill: problems.append(f"SKILL.md does not name the lesson type {t['value']}")
if ",".join(L["columns"]) not in skill: problems.append("SKILL.md does not hold the header line")
if len(skill.splitlines()) > 300: problems.append(f"SKILL.md is {len(skill.splitlines())} lines; keep it under 300")
schema = open(os.path.join(root, "level-3-files", "schema.sql")).read()
for item in L["kinds"] + L["areas"] + L["lesson_types"]:
    if f"'{item['value']}'" not in schema: problems.append(f"schema.sql does not seed {item['value']}")

# 4. the Claude plugin: the skill plus three commands
plug = os.path.join(root, "level-2-files", "claude-plugin", "learnings-database")
shutil.rmtree(plug, ignore_errors=True)
for d in (".claude-plugin", "commands", os.path.join("skills", "learnings-database")):
    os.makedirs(os.path.join(plug, d))
shutil.copy(os.path.join(root, "base", "SKILL.md"), os.path.join(plug, "skills", "learnings-database"))
shutil.copy(os.path.join(here, "img", "icon.png"), os.path.join(plug, ".claude-plugin", "icon.png"))
json.dump({"name": "learnings-database", "version": "0.2.0",
           "description": "Keep a learnings log you own: log a lesson in one line, get the rules back before similar work, "
                          "and review what is waiting each week. Nothing is saved or trusted without your yes.",
           "author": {"name": "Bradley Ross", "url": "https://www.linkedin.com/in/bradaross/"}, "license": "Apache-2.0",
           "homepage": "https://github.com/bar181/practical-ai/tree/main/projects/learnings-database",
           "keywords": ["learnings", "lessons learned", "after-action review"]},
          open(os.path.join(plug, ".claude-plugin", "plugin.json"), "w"), indent=2)
COMMANDS = {
    "log": ("Log a lesson to your learnings log", "what happened, and what you expected",
            "Use the learnings-database skill to log this lesson. Show me the row and ask before saving anything."),
    "before-i-start": ("Get the rules from your learnings log for the work you are about to start", "the work, and its project",
                       "Use the learnings-database skill: before I start this work, find the accepted rules that apply."),
    "weekly-review": ("Review the lessons waiting in your learnings log", "",
                      "Use the learnings-database skill to run the weekly review. Suggest; change nothing without my yes."),
}
for name, (desc, hint, body) in COMMANDS.items():
    head = f"---\ndescription: {desc}\n" + (f"argument-hint: {hint}\n" if hint else "") + "---\n\n"
    open(os.path.join(plug, "commands", name + ".md"), "w").write(head + body + "\n\n$ARGUMENTS\n")

if problems:
    print("\n".join("PROBLEM: " + p for p in problems)); sys.exit(1)
print("checks: ok")
